import requests

BASE = "https://api.example.com/v2"
A = {"Authorization": "Bearer <token do tester-a>"}
B = {"Authorization": "Bearer <token do tester-b>"}

# objetos que a conta A possui (listados com o token da própria A)
ids = [o["id"] for o in requests.get(f"{BASE}/invoices", headers=A, timeout=10).json()]

for oid in ids:
    r = requests.get(f"{BASE}/invoices/{oid}", headers=B, timeout=10)
    verdict = "VULNERABLE" if r.status_code == 200 else "ok"
    print(f"{oid}: B -> {r.status_code} {verdict}")
